# ============================================================
# MONTE CARLO SIMULATION
# RELIABILITY + SENSITIVITY ANALYSIS
# ============================================================
#
# IMPORTANT:
# This script uses the FINAL Monte Carlo parameter file
# generated by Probability_Parameters.R.
#
# It does NOT read raw or cleaned CBR/traffic data.
#
# ============================================================


# ============================================================
# 1. USER INPUTS
# ============================================================

# ------------------------------------------------------------
# FINAL PARAMETER FILE
# ------------------------------------------------------------

parameter_file <-
  "E:/Pavement_Reliability_Project/_R_Results/Monte_Carlo_Final_Input_Parameters.csv"


# ------------------------------------------------------------
# OUTPUT FOLDER
# ------------------------------------------------------------

output_folder <-
  "E:/Pavement_Reliability_Project/_R_Results"


# ------------------------------------------------------------
# NUMBER OF SIMULATIONS
# ------------------------------------------------------------

N_sim <- 10000


# ------------------------------------------------------------
# RANDOM SEED
# ------------------------------------------------------------

set.seed(2026)


# ============================================================
# 2. CREATE OUTPUT FOLDER
# ============================================================

if (!dir.exists(output_folder)) {
  
  dir.create(
    output_folder,
    recursive = TRUE
  )
}


# ============================================================
# 3. READ FINAL MONTE CARLO PARAMETERS
# ============================================================

MC_parameters <-
  read.csv(
    parameter_file,
    stringsAsFactors = FALSE
  )


cat("\n============================================\n")
cat("FINAL MONTE CARLO INPUT PARAMETERS\n")
cat("============================================\n")

print(MC_parameters)


# ============================================================
# 4. CHECK REQUIRED PARAMETERS
# ============================================================

required_parameters <- c(
  "CBR",
  "Traffic_Growth_Rate",
  "Bituminous_MR",
  "Granular_MR"
)


if (
  !all(
    required_parameters %in%
    MC_parameters$Parameter
  )
) {
  
  stop(
    "One or more required parameters are missing."
  )
}


# ============================================================
# 5. EXTRACT PARAMETERS
# ============================================================


# ------------------------------------------------------------
# CBR
# ------------------------------------------------------------

CBR_baseline <-
  MC_parameters$Baseline[
    MC_parameters$Parameter == "CBR"
  ]

CBR_SD <-
  MC_parameters$SD[
    MC_parameters$Parameter == "CBR"
  ]

CBR_distribution <-
  MC_parameters$Distribution[
    MC_parameters$Parameter == "CBR"
  ]


# ------------------------------------------------------------
# TRAFFIC GROWTH
# ------------------------------------------------------------

Growth_baseline_percent <-
  MC_parameters$Baseline[
    MC_parameters$Parameter ==
      "Traffic_Growth_Rate"
  ]

Growth_SD_percent <-
  MC_parameters$SD[
    MC_parameters$Parameter ==
      "Traffic_Growth_Rate"
  ]

Growth_distribution <-
  MC_parameters$Distribution[
    MC_parameters$Parameter ==
      "Traffic_Growth_Rate"
  ]


# ------------------------------------------------------------
# BITUMINOUS MODULUS
# ------------------------------------------------------------

Bituminous_MR_baseline <-
  MC_parameters$Baseline[
    MC_parameters$Parameter ==
      "Bituminous_MR"
  ]

Bituminous_MR_SD <-
  MC_parameters$SD[
    MC_parameters$Parameter ==
      "Bituminous_MR"
  ]

Bituminous_distribution <-
  MC_parameters$Distribution[
    MC_parameters$Parameter ==
      "Bituminous_MR"
  ]


# ------------------------------------------------------------
# GRANULAR MODULUS
# ------------------------------------------------------------

Granular_MR_baseline <-
  MC_parameters$Baseline[
    MC_parameters$Parameter ==
      "Granular_MR"
  ]

Granular_MR_SD <-
  MC_parameters$SD[
    MC_parameters$Parameter ==
      "Granular_MR"
  ]

Granular_distribution <-
  MC_parameters$Distribution[
    MC_parameters$Parameter ==
      "Granular_MR"
  ]


# ============================================================
# 6. PROJECT DESIGN INPUTS
# ============================================================

# These are fixed project/design values.

Design_CVPD <- 3086

Design_MSA <- 95

Design_Period_Years <- 20

VDF <- 3.9

LDF <- 0.50


# ============================================================
# 7. CONVERT LOGNORMAL PARAMETERS
# ============================================================
#
# For a lognormal variable:
#
# meanlog =
# log(mean^2 / sqrt(mean^2 + SD^2))
#
# sdlog =
# sqrt(log(1 + SD^2 / mean^2))
#
# ============================================================


# ------------------------------------------------------------
# CBR
# ------------------------------------------------------------

CBR_meanlog <-
  log(
    CBR_baseline^2 /
      sqrt(
        CBR_baseline^2 +
          CBR_SD^2
      )
  )


CBR_sdlog <-
  sqrt(
    log(
      1 +
        (
          CBR_SD^2 /
            CBR_baseline^2
        )
    )
  )


# ------------------------------------------------------------
# BITUMINOUS MR
# ------------------------------------------------------------

Bituminous_meanlog <-
  log(
    Bituminous_MR_baseline^2 /
      sqrt(
        Bituminous_MR_baseline^2 +
          Bituminous_MR_SD^2
      )
  )


Bituminous_sdlog <-
  sqrt(
    log(
      1 +
        (
          Bituminous_MR_SD^2 /
            Bituminous_MR_baseline^2
        )
    )
  )


# ------------------------------------------------------------
# GRANULAR MR
# ------------------------------------------------------------

Granular_meanlog <-
  log(
    Granular_MR_baseline^2 /
      sqrt(
        Granular_MR_baseline^2 +
          Granular_MR_SD^2
      )
  )


Granular_sdlog <-
  sqrt(
    log(
      1 +
        (
          Granular_MR_SD^2 /
            Granular_MR_baseline^2
        )
    )
  )


# ============================================================
# 8. MONTE CARLO GENERATION
# ============================================================


# ------------------------------------------------------------
# CBR
# ------------------------------------------------------------

CBR_sim <-
  rlnorm(
    N_sim,
    meanlog = CBR_meanlog,
    sdlog = CBR_sdlog
  )


# Ensure CBR remains > 5%

while (
  any(CBR_sim <= 5)
) {
  
  index <-
    which(CBR_sim <= 5)
  
  CBR_sim[index] <-
    rlnorm(
      length(index),
      meanlog = CBR_meanlog,
      sdlog = CBR_sdlog
    )
}


# ------------------------------------------------------------
# TRAFFIC GROWTH
# ------------------------------------------------------------

Growth_sim_percent <-
  rnorm(
    N_sim,
    mean = Growth_baseline_percent,
    sd = Growth_SD_percent
  )


# Prevent negative growth

while (
  any(Growth_sim_percent <= 0)
) {
  
  index <-
    which(
      Growth_sim_percent <= 0
    )
  
  Growth_sim_percent[index] <-
    rnorm(
      length(index),
      mean = Growth_baseline_percent,
      sd = Growth_SD_percent
    )
}


# Convert percentage to decimal

Growth_sim <-
  Growth_sim_percent / 100


# ------------------------------------------------------------
# BITUMINOUS MODULUS
# ------------------------------------------------------------

Bituminous_MR_sim <-
  rlnorm(
    N_sim,
    meanlog = Bituminous_meanlog,
    sdlog = Bituminous_sdlog
  )


# ------------------------------------------------------------
# GRANULAR MODULUS
# ------------------------------------------------------------

Granular_MR_sim <-
  rlnorm(
    N_sim,
    meanlog = Granular_meanlog,
    sdlog = Granular_sdlog
  )


# ============================================================
# 9. CALCULATE SUBGRADE RESILIENT MODULUS
# ============================================================
#
# IRC:37-2018:
#
# MR = 17.6 × CBR^0.64
#
# ============================================================

Subgrade_MR_sim <-
  17.6 *
  CBR_sim^0.64


# ============================================================
# 10. CALCULATE CUMULATIVE TRAFFIC
# ============================================================
#
# Initial design CVPD = 3086
#
# Traffic in each year:
#
# CVPD_year =
# Initial CVPD × (1 + r)^year
#
# ============================================================


Year <- 1:Design_Period_Years


# Matrix of yearly traffic for every simulation

Traffic_matrix <-
  outer(
    Growth_sim,
    Year,
    FUN = function(r, y) {
      
      Design_CVPD *
        (1 + r)^y
    }
  )


# ============================================================
# 11. CUMULATIVE COMMERCIAL VEHICLES
# ============================================================

Cumulative_CVPD <-
  rowSums(
    Traffic_matrix
  )


# ============================================================
# 12. CONVERT TRAFFIC TO MSA
# ============================================================
#
# MSA =
#
# cumulative CVPD
# × 365
# × VDF
# × LDF
# ÷ 1,000,000
#
# ============================================================

MSA_sim <-
  (
    Cumulative_CVPD *
      365 *
      VDF *
      LDF
  ) /
  1000000


# ============================================================
# 13. RELIABILITY ANALYSIS
# ============================================================
#
# Criterion:
#
# Simulated MSA <= Design MSA
#
# Design MSA = 95
#
# ============================================================

Pass <-
  MSA_sim <= Design_MSA


Fail <-
  MSA_sim > Design_MSA


Reliability_percent <-
  mean(Pass) *
  100


Probability_of_failure_percent <-
  mean(Fail) *
  100


# ============================================================
# 14. SAFETY MARGIN
# ============================================================

Safety_Margin_MSA <-
  Design_MSA -
  MSA_sim


# Positive = below design traffic
# Negative = exceeds design traffic


# ============================================================
# 15. MONTE CARLO RESULTS DATASET
# ============================================================

MC_results <-
  data.frame(
    
    Simulation_ID =
      1:N_sim,
    
    CBR_percent =
      CBR_sim,
    
    Growth_Rate_percent =
      Growth_sim_percent,
    
    Bituminous_MR_MPa =
      Bituminous_MR_sim,
    
    Granular_MR_MPa =
      Granular_MR_sim,
    
    Subgrade_MR_MPa =
      Subgrade_MR_sim,
    
    Design_CVPD =
      Design_CVPD,
    
    VDF =
      VDF,
    
    LDF =
      LDF,
    
    Design_Period_Years =
      Design_Period_Years,
    
    Design_MSA =
      Design_MSA,
    
    Simulated_MSA =
      MSA_sim,
    
    Safety_Margin_MSA =
      Safety_Margin_MSA,
    
    Pass =
      Pass,
    
    Fail =
      Fail
  )


# ============================================================
# 16. SUMMARY STATISTICS
# ============================================================

summary_results <-
  data.frame(
    
    Parameter = c(
      
      "Number of simulations",
      
      "Baseline CBR (%)",
      
      "Mean simulated CBR (%)",
      
      "SD simulated CBR (%)",
      
      "Baseline traffic growth (%)",
      
      "Mean simulated growth (%)",
      
      "SD simulated growth (%)",
      
      "Baseline bituminous MR (MPa)",
      
      "Mean simulated bituminous MR (MPa)",
      
      "SD simulated bituminous MR (MPa)",
      
      "Baseline granular MR (MPa)",
      
      "Mean simulated granular MR (MPa)",
      
      "SD simulated granular MR (MPa)",
      
      "Mean subgrade MR (MPa)",
      
      "Baseline design MSA",
      
      "Mean simulated MSA",
      
      "Median simulated MSA",
      
      "SD simulated MSA",
      
      "5th percentile MSA",
      
      "95th percentile MSA",
      
      "Reliability (%)",
      
      "Probability of failure (%)"
    ),
    
    Value = c(
      
      N_sim,
      
      CBR_baseline,
      
      mean(CBR_sim),
      
      sd(CBR_sim),
      
      Growth_baseline_percent,
      
      mean(Growth_sim_percent),
      
      sd(Growth_sim_percent),
      
      Bituminous_MR_baseline,
      
      mean(Bituminous_MR_sim),
      
      sd(Bituminous_MR_sim),
      
      Granular_MR_baseline,
      
      mean(Granular_MR_sim),
      
      sd(Granular_MR_sim),
      
      mean(Subgrade_MR_sim),
      
      Design_MSA,
      
      mean(MSA_sim),
      
      median(MSA_sim),
      
      sd(MSA_sim),
      
      quantile(
        MSA_sim,
        0.05
      ),
      
      quantile(
        MSA_sim,
        0.95
      ),
      
      Reliability_percent,
      
      Probability_of_failure_percent
    )
  )


# ============================================================
# 17. SENSITIVITY ANALYSIS
# ============================================================
#
# Spearman rank correlation between each uncertain
# input and simulated MSA.
#
# NOTE:
# MSA is directly affected by traffic growth.
#
# CBR and material modulus do NOT directly enter the
# traffic MSA equation.
#
# Therefore, their correlation with MSA should NOT be
# interpreted as structural pavement sensitivity.
#
# ============================================================


Sensitivity_CBR <-
  cor(
    CBR_sim,
    MSA_sim,
    method = "spearman"
  )


Sensitivity_Growth <-
  cor(
    Growth_sim,
    MSA_sim,
    method = "spearman"
  )


Sensitivity_Bituminous <-
  cor(
    Bituminous_MR_sim,
    MSA_sim,
    method = "spearman"
  )


Sensitivity_Granular <-
  cor(
    Granular_MR_sim,
    MSA_sim,
    method = "spearman"
  )


Sensitivity_results <-
  data.frame(
    
    Parameter = c(
      
      "CBR",
      
      "Traffic Growth Rate",
      
      "Bituminous MR",
      
      "Granular MR"
    ),
    
    Spearman_Correlation = c(
      
      Sensitivity_CBR,
      
      Sensitivity_Growth,
      
      Sensitivity_Bituminous,
      
      Sensitivity_Granular
    )
  )


Sensitivity_results$Absolute_Correlation <-
  abs(
    Sensitivity_results$Spearman_Correlation
  )


Sensitivity_results$Rank <-
  rank(
    -Sensitivity_results$Absolute_Correlation,
    ties.method = "first"
  )


Sensitivity_results <-
  Sensitivity_results[
    order(
      Sensitivity_results$Rank
    ),
  ]


# ============================================================
# 18. PRINT RESULTS
# ============================================================

cat("\n")
cat("============================================================\n")
cat("MONTE CARLO RESULTS\n")
cat("============================================================\n")

cat(
  "Number of simulations:",
  N_sim,
  "\n"
)

cat(
  "Design CVPD:",
  Design_CVPD,
  "\n"
)

cat(
  "Design MSA:",
  Design_MSA,
  "\n"
)

cat(
  "Mean simulated MSA:",
  round(
    mean(MSA_sim),
    2
  ),
  "\n"
)

cat(
  "Median simulated MSA:",
  round(
    median(MSA_sim),
    2
  ),
  "\n"
)

cat(
  "5th percentile MSA:",
  round(
    quantile(
      MSA_sim,
      0.05
    ),
    2
  ),
  "\n"
)

cat(
  "95th percentile MSA:",
  round(
    quantile(
      MSA_sim,
      0.95
    ),
    2
  ),
  "\n"
)

cat(
  "Reliability:",
  round(
    Reliability_percent,
    2
  ),
  "%\n"
)

cat(
  "Probability of failure:",
  round(
    Probability_of_failure_percent,
    2
  ),
  "%\n"
)


# ============================================================
# 19. PRINT SENSITIVITY RESULTS
# ============================================================

cat("\n")
cat("============================================================\n")
cat("SENSITIVITY ANALYSIS\n")
cat("============================================================\n")

print(
  Sensitivity_results
)


# ============================================================
# 20. SAVE FULL MONTE CARLO DATA
# ============================================================

write.csv(
  
